-- 修改土地利用现状里面的 扣除地系数和面积code
UPDATE sys_layer_type_fields set code = 'kcmj' where abbreviation = 'xztb' and code = 'tkmj';
UPDATE sys_layer_type_fields set code = 'kcxs' where abbreviation = 'xztb' and code = 'tkxs';

UPDATE sys_layer_type_fields set DELETE_FLAG = 1 where abbreviation in ('ckq','tkq','tewc') and code = 'id';

ALTER TABLE `sys_layer_type` ADD INDEX `abbreviation_index`(`abbreviation`);


